        public static byte[] Build(Dictionary<string,object> args){
            var slides=AgentTaskState.Get<List<Dictionary<string,object>>>(args,"slides");if(slides==null||slides.Count<1||slides.Count>20)throw new InvalidDataException("Agent 修改无效。");
            using(var memory=new MemoryStream()){using(var zip=new ZipArchive(memory,ZipArchiveMode.Create,true)){
                var types=new StringBuilder("<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/ppt/presentation.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml\"/><Override PartName=\"/ppt/slideMasters/slideMaster1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.presentationml.slideMaster+xml\"/><Override PartName=\"/ppt/slideLayouts/slideLayout1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.presentationml.slideLayout+xml\"/>");
                string ids="",rels="<Relationships xmlns=\""+PKG+"\"><Relationship Id=\"master\" Type=\""+R+"/slideMaster\" Target=\"slideMasters/slideMaster1.xml\"/>";
                for(int n=0;n<slides.Count;n++){int i=n+1;ids+="<p:sldId id=\""+(255+i)+"\" r:id=\"s"+i+"\"/>";rels+="<Relationship Id=\"s"+i+"\" Type=\""+R+"/slide\" Target=\"slides/slide"+i+".xml\"/>";types.Append("<Override PartName=\"/ppt/slides/slide"+i+".xml\" ContentType=\"application/vnd.openxmlformats-officedocument.presentationml.slide+xml\"/>");var s=slides[n];var bullets=AgentTaskState.Get<List<string>>(s,"bullets")??new List<string>();
                    Put(zip,"ppt/slides/slide"+i+".xml","<p:sld xmlns:p=\""+P+"\" xmlns:a=\""+A+"\" xmlns:r=\""+R+"\"><p:cSld><p:spTree>"+Tree()+Text(2,"Title",Convert.ToString(s["title"]),548640,914400,3200)+Text(3,"Body",String.Join("\n",bullets.Select(b=>"• "+b)),1737360,4389120,2000)+"</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>");
                    Put(zip,"ppt/slides/_rels/slide"+i+".xml.rels","<Relationships xmlns=\""+PKG+"\"><Relationship Id=\"layout\" Type=\""+R+"/slideLayout\" Target=\"../slideLayouts/slideLayout1.xml\"/></Relationships>");
                }
                Put(zip,"[Content_Types].xml",types+"<Override PartName=\"/ppt/theme/theme1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.theme+xml\"/></Types>");Put(zip,"_rels/.rels","<Relationships xmlns=\""+PKG+"\"><Relationship Id=\"presentation\" Type=\""+R+"/officeDocument\" Target=\"ppt/presentation.xml\"/></Relationships>");
                Put(zip,"ppt/presentation.xml","<p:presentation xmlns:p=\""+P+"\" xmlns:a=\""+A+"\" xmlns:r=\""+R+"\"><p:sldMasterIdLst><p:sldMasterId id=\"2147483648\" r:id=\"master\"/></p:sldMasterIdLst><p:sldIdLst>"+ids+"</p:sldIdLst><p:sldSz cx=\"12192000\" cy=\"6858000\" type=\"screen16x9\"/><p:notesSz cx=\"6858000\" cy=\"9144000\"/></p:presentation>");Put(zip,"ppt/_rels/presentation.xml.rels",rels+"</Relationships>");
                Put(zip,"ppt/slideMasters/slideMaster1.xml","<p:sldMaster xmlns:p=\""+P+"\" xmlns:a=\""+A+"\" xmlns:r=\""+R+"\"><p:cSld><p:spTree>"+Tree()+"</p:spTree></p:cSld><p:clrMap accent1=\"accent1\" accent2=\"accent2\" accent3=\"accent3\" accent4=\"accent4\" accent5=\"accent5\" accent6=\"accent6\" bg1=\"lt1\" bg2=\"lt2\" folHlink=\"folHlink\" hlink=\"hlink\" tx1=\"dk1\" tx2=\"dk2\"/><p:sldLayoutIdLst><p:sldLayoutId id=\"2147483649\" r:id=\"layout\"/></p:sldLayoutIdLst><p:txStyles><p:titleStyle/><p:bodyStyle/><p:otherStyle/></p:txStyles></p:sldMaster>");
                Put(zip,"ppt/slideMasters/_rels/slideMaster1.xml.rels","<Relationships xmlns=\""+PKG+"\"><Relationship Id=\"layout\" Type=\""+R+"/slideLayout\" Target=\"../slideLayouts/slideLayout1.xml\"/><Relationship Id=\"theme\" Type=\""+R+"/theme\" Target=\"../theme/theme1.xml\"/></Relationships>");
                Put(zip,"ppt/slideLayouts/slideLayout1.xml","<p:sldLayout xmlns:p=\""+P+"\" xmlns:a=\""+A+"\" type=\"blank\" preserve=\"1\"><p:cSld name=\"Blank\"><p:spTree>"+Tree()+"</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sldLayout>");
                Put(zip,"ppt/slideLayouts/_rels/slideLayout1.xml.rels","<Relationships xmlns=\""+PKG+"\"><Relationship Id=\"master\" Type=\""+R+"/slideMaster\" Target=\"../slideMasters/slideMaster1.xml\"/></Relationships>");
                string colors="";var names=new[]{"dk1","lt1","dk2","lt2","accent1","accent2","accent3","accent4","accent5","accent6","hlink","folHlink"};var values=new[]{"222222","FFFFFF","444444","F2F2F2","5E82B8","6A9A85","D0A25E","9C86B9","7899A5","B87D82","326DCE","8658A5"};for(int n=0;n<names.Length;n++)colors+="<a:"+names[n]+"><a:srgbClr val=\""+values[n]+"\"/></a:"+names[n]+">";
